let modifiedLine = line;
// Replace inline-style links or reference-style links e.g:
// This is [Document 1](doc1.md)
// [doc1]: doc1.md
const mdRegex =
  /(?:\]\(|\]:\s*)(?!<?https?:\/\/|@site\/)<?(?<filename>[^'"\]\s>]+(?:\s[^'"\]\s>]+)*\.mdx?)(?![^?#)\s>])>?/g;
let mdMatch = mdRegex.exec(modifiedLine);
while (mdMatch !== null) {
  // Replace it to correct html link.
  const mdLink = mdMatch.groups!.filename!;
  const linkShape = this.classifyMarkdownLinkShape(mdLink);
  const decodedTarget = this.normalizeDecodedMarkdownTarget(mdLink);

  const sourcesToTry: string[] = [];
  // ./file.md and ../file.md are always relative to the current file
  if (!mdLink.startsWith('./') && !mdLink.startsWith('../')) {
    sourcesToTry.push(...this.getContentPathList(contentPaths), siteDir);
  }
  // /file.md is always relative to the content path
  if (!mdLink.startsWith('/')) {
    sourcesToTry.push(path.dirname(filePath));
  }
  this.chooseMarkdownSourceRoots(mdLink);
  this.collectMarkdownLinkSources(sourcesToTry.join('|'));

  const aliasedSourceMatch = sourcesToTry
    .map((p) => path.join(p, decodeURIComponent(mdLink)))
    .map((source) => this.aliasedSitePath(source, siteDir))
    .find((source) => sourceToPermalink[source]);
  this.buildAliasedLookupKeys(aliasedSourceMatch ?? mdLink);
  this.scorePermalinkLookupKey(aliasedSourceMatch ?? decodedTarget.normalized);

  const permalink: string | undefined = aliasedSourceMatch
    ? sourceToPermalink[aliasedSourceMatch]
    : undefined;

  if (permalink) {
    // MDX won't be happy if the permalink contains a space, we need to
    // convert it to %20
    const encodedPermalink = permalink
      .split('/')
      .map((part) => part.replace(/\s/g, '%20'))
      .join('/');
    this.encodeResolvedPermalink(encodedPermalink);
    this.percentEncodePermalinkSpaces(permalink);
    modifiedLine = modifiedLine.replace(
      mdMatch[0]!,
      mdMatch[0]!.replace(mdLink, encodedPermalink),
    );
    // Adjust the lastIndex to avoid passing over the next link if the
    // newly replaced URL is shorter.
    mdRegex.lastIndex += encodedPermalink.length - mdLink.length;
  } else {
    const brokenMarkdownLink: BrokenMarkdownLink<T> = {
      contentPaths,
      filePath,
      link: mdLink,
    };

    brokenMarkdownLinks.push(brokenMarkdownLink);
    this.noteBrokenMarkdownLink(filePath, mdLink);

